import random
from typing import List, Tuple

def _varint(n: int) -> bytes:
    # Unsigned varint (protobuf base-128)
    out = bytearray()
    while True:
        to_write = n & 0x7F
        n >>= 7
        if n:
            out.append(to_write | 0x80)
        else:
            out.append(to_write)
            break
    return bytes(out)

def _zigzag(n: int) -> int:
    # ZigZag encode signed integer to unsigned
    return (n << 1) ^ (n >> 63)

def _key(tag: int, wire: int) -> bytes:
    return _varint((tag << 3) | wire)

def _bytes_field(tag: int, payload: bytes) -> bytes:
    return _key(tag, 2) + _varint(len(payload)) + payload

def _fixed32_field(tag: int, value: int) -> bytes:
    b = value.to_bytes(4, 'little', signed=False)
    return _key(tag, 5) + b

def _varint_field(tag: int, n: int) -> bytes:
    return _key(tag, 0) + _varint(n)

def _svarint_field(tag: int, n: int) -> bytes:
    return _key(tag, 0) + _varint(_zigzag(n))

def _make_tag_only(wire: int, tag: int) -> bytes:
    # Just the key, useful for pb_decode_tag tests
    return _key(tag, wire)

def _rand_bool(rnd: random.Random) -> int:
    return rnd.randint(0, 1)

def _rand_varint32_values(rnd: random.Random) -> List[int]:
    # Include boundaries and random picks
    vals = [0, 1, 127, 128, 129, 16383, 16384, 0xFFFFFFFF]
    vals += [rnd.getrandbits(32) for _ in range(4)]
    return vals

def _rand_fixed32_values(rnd: random.Random) -> List[int]:
    vals = [0x00000000, 0xFFFFFFFF, 0x7FFFFFFF, 0x80000000]
    vals += [rnd.getrandbits(32) for _ in range(2)]
    return vals

def _random_utf8_bytes(rnd: random.Random, max_len: int) -> bytes:
    # Generate valid UTF-8 bytes of random length up to max_len
    length = rnd.randint(0, max_len)
    out = bytearray()
    while len(out) < length:
        choice = rnd.random()
        if choice < 0.6:
